create schema if not exists extensions;
create extension if not exists btree_gist with schema extensions;
set search_path = public, extensions;
grant usage on schema public to anon,authenticated;
create table public.profiles(id uuid primary key references auth.users on delete cascade,display_name text,created_at timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references auth.users on delete cascade,role text not null default 'customer' check(role in ('customer','admin')),created_at timestamptz not null default now());
create table public.malls(id uuid primary key default gen_random_uuid(),name text not null,timezone text not null default 'Asia/Kuala_Lumpur',is_active boolean not null default true,created_at timestamptz not null default now());
create table public.zones(id uuid primary key default gen_random_uuid(),mall_id uuid not null references public.malls,name text not null,floor text not null,description text,is_active boolean not null default true,map_region_key text not null,created_at timestamptz not null default now(),unique(mall_id,name));
create table public.bays(id uuid primary key default gen_random_uuid(),zone_id uuid not null references public.zones,label text not null,bay_type text not null default 'standard',is_active boolean not null default true,created_at timestamptz not null default now(),unique(zone_id,label));
create table public.destinations(id uuid primary key default gen_random_uuid(),mall_id uuid not null references public.malls,name text not null,category text not null,created_at timestamptz not null default now(),unique(mall_id,name));
create table public.zone_destination_routes(id uuid primary key default gen_random_uuid(),zone_id uuid not null references public.zones,destination_id uuid not null references public.destinations,walking_distance_m integer not null check(walking_distance_m>=0),is_step_free boolean,is_verified boolean not null default false,route_description text,unique(zone_id,destination_id));
create table public.reservations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,bay_id uuid not null references public.bays,destination_id uuid references public.destinations,preference text not null check(preference in ('none','shorter_walk','step_free')),start_at timestamptz not null,end_at timestamptz not null,status text not null default 'confirmed' check(status in ('confirmed','checked_in','completed','cancelled','no_show')),idempotency_key uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),cancelled_at timestamptz,checked_in_at timestamptz,completed_at timestamptz,check(end_at>start_at),unique(user_id,idempotency_key),exclude using gist(bay_id with =,tstzrange(start_at,end_at,'[)') with &&) where(status in ('confirmed','checked_in')));
create index reservations_user on public.reservations(user_id,start_at);
create index bays_zone on public.bays(zone_id);
create table public.booking_events(id uuid primary key default gen_random_uuid(),reservation_id uuid not null references public.reservations,actor_user_id uuid references auth.users,event_type text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create index events_reservation on public.booking_events(reservation_id);
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles where user_id=auth.uid() and role='admin')$$;
create function public.new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,display_name) values(new.id,left(new.raw_user_meta_data->>'display_name',100));insert into public.user_roles(user_id) values(new.id);return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_user();
do $$declare t text;begin foreach t in array array['profiles','user_roles','malls','zones','bays','destinations','zone_destination_routes','reservations','booking_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end$$;
grant select on public.malls,public.zones,public.bays,public.destinations,public.zone_destination_routes to anon,authenticated;
create policy inventory_malls on public.malls for select using(true);
create policy inventory_zones on public.zones for select using(true);
create policy inventory_bays on public.bays for select using(true);
create policy inventory_destinations on public.destinations for select using(true);
create policy inventory_routes on public.zone_destination_routes for select using(true);
grant select on public.reservations,public.profiles,public.user_roles,public.booking_events to authenticated;
create policy own_profile on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy own_role on public.user_roles for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy own_booking on public.reservations for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy admin_events on public.booking_events for select to authenticated using(public.is_admin());
create function public.validate_interval(s timestamptz,e timestamptz) returns void language plpgsql set search_path='' as $$begin if s is null or e is null or s<=now() or s>now()+interval '30 days' or e-s<interval '30 minutes' or e-s>interval '8 hours' then raise exception 'INVALID_INTERVAL' using errcode='22023';end if;end$$;
create function public.availability(p_mall uuid,p_start timestamptz,p_end timestamptz,p_destination uuid default null) returns table("zoneId" uuid,"zoneName" text,floor text,"availableBayCount" bigint,"walkingDistanceM" integer,"stepFree" boolean,verified boolean) language plpgsql security definer set search_path='' as $$begin perform public.validate_interval(p_start,p_end);return query select z.id,z.name,z.floor,count(b.id),r.walking_distance_m,r.is_step_free,coalesce(r.is_verified,false) from public.zones z join public.malls m on m.id=z.mall_id left join public.bays b on b.zone_id=z.id and b.is_active and b.bay_type='standard' and not exists(select 1 from public.reservations v where v.bay_id=b.id and v.status in ('confirmed','checked_in') and v.start_at<p_end and v.end_at>p_start) left join public.zone_destination_routes r on r.zone_id=z.id and r.destination_id=p_destination where m.id=p_mall and m.is_active and z.is_active group by z.id,r.walking_distance_m,r.is_step_free,r.is_verified order by z.name;end$$;
create function public.reserve(p_mall uuid,p_zone uuid,p_start timestamptz,p_end timestamptz,p_destination uuid,p_preference text,p_key uuid) returns public.reservations language plpgsql security definer set search_path='' as $$declare result public.reservations;b public.bays;begin
if auth.uid() is null then raise exception 'UNAUTHENTICATED' using errcode='28000';end if;
if p_key is null then raise exception 'INVALID_KEY' using errcode='22023';end if;
perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_key::text,0));
select * into result from public.reservations where user_id=auth.uid() and idempotency_key=p_key;
if found then if result.start_at is distinct from p_start or result.end_at is distinct from p_end or result.destination_id is distinct from p_destination or result.preference is distinct from p_preference or not exists(select 1 from public.bays x join public.zones z on z.id=x.zone_id where x.id=result.bay_id and z.id=p_zone and z.mall_id=p_mall) then raise exception 'IDEMPOTENCY_CONFLICT' using errcode='23505';end if;return result;end if;
perform public.validate_interval(p_start,p_end);
if p_preference is null or p_preference not in ('none','shorter_walk','step_free') or (p_preference<>'none' and p_destination is null) then raise exception 'INVALID_PREFERENCE' using errcode='22023';end if;
if p_destination is not null and not exists(select 1 from public.destinations where id=p_destination and mall_id=p_mall) then raise exception 'INVALID_DESTINATION' using errcode='22023';end if;
perform 1 from public.zones z join public.malls m on m.id=z.mall_id where z.id=p_zone and m.id=p_mall and z.is_active and m.is_active for share of z,m;
if not found then raise exception 'ZONE_UNAVAILABLE' using errcode='P0002';end if;
if p_preference='step_free' and not exists(select 1 from public.zone_destination_routes where zone_id=p_zone and destination_id=p_destination and is_verified and is_step_free=true) then raise exception 'ROUTE_UNAVAILABLE' using errcode='P0002';end if;
for b in select * from public.bays where zone_id=p_zone and is_active and bay_type='standard' order by label for update loop
begin insert into public.reservations(user_id,bay_id,destination_id,preference,start_at,end_at,idempotency_key) values(auth.uid(),b.id,p_destination,p_preference,p_start,p_end,p_key) returning * into result;
insert into public.booking_events(reservation_id,actor_user_id,event_type) values(result.id,auth.uid(),'confirmed');return result;
exception when exclusion_violation then continue;end;
end loop;raise exception 'NO_AVAILABILITY' using errcode='23P01';end$$;
create function public.transition(p_id uuid,p_next text) returns public.reservations language plpgsql security definer set search_path='' as $$declare r public.reservations;begin
if auth.uid() is null then raise exception 'UNAUTHENTICATED' using errcode='28000';end if;
select * into r from public.reservations where id=p_id and (user_id=auth.uid() or public.is_admin()) for update;
if not found then raise exception 'NOT_FOUND' using errcode='P0002';end if;
if p_next='cancelled' then if r.user_id<>auth.uid() or r.status<>'confirmed' or r.start_at<=now() then raise exception 'INVALID_TRANSITION' using errcode='23P01';end if;
else if not public.is_admin() then raise exception 'FORBIDDEN' using errcode='42501';end if;
if not ((r.status='confirmed' and p_next='checked_in') or (r.status='checked_in' and p_next='completed') or (r.status='confirmed' and p_next='no_show' and r.end_at<=now())) then raise exception 'INVALID_TRANSITION' using errcode='23P01';end if;end if;
update public.reservations set status=p_next,updated_at=now(),cancelled_at=case when p_next='cancelled' then now() else cancelled_at end,checked_in_at=case when p_next='checked_in' then now() else checked_in_at end,completed_at=case when p_next='completed' then now() else completed_at end where id=p_id returning * into r;
insert into public.booking_events(reservation_id,actor_user_id,event_type,details) values(p_id,auth.uid(),p_next,jsonb_build_object('simulated',p_next in ('checked_in','completed')));return r;end$$;
create function public.set_bay(p_id uuid,p_active boolean) returns jsonb language plpgsql security definer set search_path='' as $$declare n integer;begin if not public.is_admin() then raise exception 'FORBIDDEN' using errcode='42501';end if;if p_active is null then raise exception 'INVALID_INPUT' using errcode='22023';end if;update public.bays set is_active=p_active where id=p_id;if not found then raise exception 'NOT_FOUND' using errcode='P0002';end if;select count(*) into n from public.reservations where bay_id=p_id and end_at>now() and status in ('confirmed','checked_in');return jsonb_build_object('is_active',p_active,'affectedReservations',n,'warning',case when not p_active and n>0 then 'Existing reservations remain allocated. Review affected bookings.' else null end);end$$;
revoke execute on function public.is_admin(),public.new_user(),public.validate_interval(timestamptz,timestamptz),public.availability(uuid,timestamptz,timestamptz,uuid),public.reserve(uuid,uuid,timestamptz,timestamptz,uuid,text,uuid),public.transition(uuid,text),public.set_bay(uuid,boolean) from public,anon,authenticated;
grant execute on function public.is_admin() to authenticated;
grant execute on function public.availability(uuid,timestamptz,timestamptz,uuid) to anon,authenticated;
grant execute on function public.reserve(uuid,uuid,timestamptz,timestamptz,uuid,text,uuid),public.transition(uuid,text),public.set_bay(uuid,boolean) to authenticated;

